from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'troubleshooting'
CATALOG = [{'id': 'trouble-gc-pause', 'concept': 'managed-runtime-gc-pause', 'domain': 'software-engineering', 'subdomain': 'runtime', 'difficulty': 'advanced', 'question': 'A managed-runtime API shows periodic stop-the-world latency spikes while CPU and downstream services look healthy. Give a troubleshooting plan for garbage-collection pauses.', 'answer': "Correlate request latency with GC pause events, heap occupancy, allocation rate, promotion/collection statistics, and safepoint logs. Inspect whether large allocation bursts or retained objects drive the heap into expensive collections. Reproduce under representative heap limits and traffic, then test changes such as reducing allocation churn, fixing retention, adjusting heap sizing, or using the runtime's appropriate collector policy. Do not tune GC from average CPU utilization alone.", 'verification_details': 'Must correlate latency with GC/safepoint evidence, inspect allocation/retention/heap pressure, and validate changes under representative load.', 'tags': ['gc', 'pause', 'heap', 'latency'], 'verification_method': 'rubric'}, {'id': 'trouble-cache-eviction-storm', 'concept': 'cache-eviction-working-set-thrash', 'domain': 'software-engineering', 'subdomain': 'caching', 'difficulty': 'intermediate', 'question': 'A service cache has a fixed 4 GB limit. Hit rate suddenly collapses after a dataset growth, and backend load rises even though request patterns look similar. How would you test for working-set thrash?', 'answer': 'Track cache occupancy, hit/miss rate, eviction rate, item-size distribution, and reuse distance/key popularity before and after the dataset change. If frequently reused entries are evicted before their next access because the active working set no longer fits, miss and eviction rates will rise together. Test a larger cache or a better admission/eviction policy under the same trace. Backend scaling alone does not restore cache locality.', 'verification_details': 'Must connect dataset growth to active working-set size, use hit/eviction/reuse evidence, and validate with capacity/policy trials.', 'tags': ['cache', 'eviction', 'working-set', 'thrash'], 'verification_method': 'rubric'}, {'id': 'trouble-full-pipe-deadlock', 'concept': 'pipe-full-mutual-wait', 'domain': 'systems-programming', 'subdomain': 'ipc', 'difficulty': 'expert', 'question': "A parent writes a large request to a child's stdin and only afterward begins reading the child's stdout. The child writes a large response before it finishes reading stdin. Both processes can hang. Diagnose the IPC deadlock.", 'answer': "Both pipes have finite capacity. The parent can block when the child's stdin pipe fills while the child simultaneously blocks because its stdout pipe is full and the parent is not reading yet. Neither side reaches the operation needed to free the other's buffer. Confirm with blocked syscall stacks and pipe directions. Use concurrent read/write handling, nonblocking/event-driven I/O, threads, or a protocol that bounds each phase so one direction cannot fill while the other is ignored.", 'verification_details': 'Must identify finite pipe buffers and mutual blocking, confirm with blocked writes/reads, and require concurrent/bounded bidirectional I/O.', 'tags': ['pipe', 'deadlock', 'ipc', 'backpressure'], 'verification_method': 'rubric'}, {'id': 'trouble-softirq-saturation', 'concept': 'network-softirq-cpu-saturation', 'domain': 'operating-systems', 'subdomain': 'networking', 'difficulty': 'expert', 'question': 'A Linux host drops packets under high network load even though application CPU usage is moderate. One CPU spends most of its time in softirq processing. How would you troubleshoot this imbalance?', 'answer': 'Measure per-CPU softirq time, NIC queue/interrupt statistics, drops, RSS/RPS/XPS configuration, IRQ affinity, and per-queue traffic. If one receive queue or interrupt is concentrated on a CPU, packet processing can saturate there before aggregate CPU reaches 100%. Test balanced queue/IRQ placement and application affinity consistent with NUMA locality. Also inspect whether a few dominant flows defeat RSS distribution. The evidence should tie packet loss to per-CPU receive-path saturation, not just total utilization.', 'verification_details': 'Must inspect per-CPU softirq/IRQ and NIC queue distribution, correlate drops with a saturated receive path, and test affinity/RSS balance.', 'tags': ['softirq', 'nic', 'rss', 'packet-drop'], 'verification_method': 'rubric'}, {'id': 'trouble-thermal-throttle', 'concept': 'cpu-thermal-throttling-performance', 'domain': 'computer-architecture', 'subdomain': 'thermal', 'difficulty': 'advanced', 'question': 'A compute job starts fast but throughput falls after several minutes while utilization remains near 100%. Clock frequency drops at the same time. Troubleshoot thermal throttling.', 'answer': 'Record package/core temperature, effective clock, power-limit/thermal-throttle flags, fan behavior, and throughput over time. A repeatable frequency drop that begins near thermal or power limits and tracks throughput loss supports throttling. Test cooling, airflow, fan policy, power-limit configuration, and a reduced sustained load. High utilization alone does not mean the CPU is running at its expected frequency.', 'verification_details': 'Must correlate throughput with temperature/effective clock and throttle flags, distinguish thermal/power limits, and validate with cooling or sustained-load changes.', 'tags': ['thermal', 'frequency', 'throttling', 'cpu'], 'verification_method': 'rubric'}, {'id': 'trouble-uart-framing', 'concept': 'uart-baud-clock-framing-errors', 'domain': 'embedded-systems', 'subdomain': 'serial', 'difficulty': 'intermediate', 'question': 'An MCU UART receives correct data at room temperature but shows framing errors at temperature extremes. Cabling is unchanged. What should be measured?', 'answer': 'Measure the actual transmitter and receiver baud/bit timing across temperature, including oscillator tolerance and clock-source drift. Compare the combined baud error with UART sampling tolerance, and inspect signal integrity with a logic analyzer/oscilloscope. If timing moves out of margin as the oscillator drifts, use a more accurate clock, calibration, or a baud/divider choice with lower error. Do not treat framing errors as purely a software parser issue.', 'verification_details': 'Must measure actual baud timing/clock drift and signal waveform, compare against sampling tolerance, and connect the fix to clock accuracy or configuration.', 'tags': ['uart', 'baud', 'clock-drift', 'framing'], 'verification_method': 'rubric'}, {'id': 'trouble-replication-lag-compaction', 'concept': 'replication-lag-storage-compaction', 'domain': 'distributed-systems', 'subdomain': 'replication', 'difficulty': 'advanced', 'question': 'A storage replica periodically falls minutes behind its leader. Network utilization is low, but the lag coincides with heavy local compaction and disk latency. Give a troubleshooting plan.', 'answer': 'Correlate replication apply rate and queue depth with compaction activity, disk latency/IOPS, CPU, and write amplification. If received replication data accumulates while local storage stalls and catches up after compaction ends, storage contention is the likely limiter. Test compaction scheduling/rate limits, storage isolation, and resource headroom while holding incoming replication rate constant. Low network usage does not rule out lag when the replica cannot apply data fast enough.', 'verification_details': 'Must distinguish receive bandwidth from local apply capacity, correlate lag with compaction/storage metrics, and validate by changing compaction/resource scheduling.', 'tags': ['replication', 'compaction', 'storage', 'lag'], 'verification_method': 'rubric'}, {'id': 'trouble-gpu-input-starvation', 'concept': 'gpu-dataloader-input-starvation', 'domain': 'compute-model-infrastructure', 'subdomain': 'training-performance', 'difficulty': 'expert', 'question': 'GPU utilization oscillates between high compute bursts and long idle gaps. Kernel execution is fast, but batches arrive irregularly from the input pipeline. Troubleshoot input starvation.', 'answer': 'Use an end-to-end timeline that includes data loading, decoding/augmentation, host-to-device transfer, queue depth, and GPU kernels. Measure loader worker utilization, storage throughput, CPU saturation, batch preparation time, and prefetch occupancy. If the GPU repeatedly drains the ready-batch queue and waits for host preparation, optimize or parallelize the input path, cache/preprocess expensive transforms, tune bounded prefetch/workers, and overlap transfers where appropriate. Increasing model compute will only hide, not fix, the supply bottleneck.', 'verification_details': 'Must show GPU idle time coinciding with empty/late input queues, profile loader/storage/CPU stages, and test input-path changes rather than GPU-only tuning.', 'tags': ['gpu', 'dataloader', 'input-pipeline', 'profiling'], 'verification_method': 'rubric'}, {'id': 'trouble-noisy-neighbor', 'concept': 'shared-host-noisy-neighbor', 'domain': 'engineering-reasoning', 'subdomain': 'capacity', 'difficulty': 'advanced', 'question': 'A service meets latency targets on a dedicated host but becomes erratic when colocated with another workload. CPU averages look acceptable. How would you test for a noisy-neighbor effect?', 'answer': 'Measure shared-resource contention, not just average CPU: per-cgroup CPU throttling/run delay, memory bandwidth, LLC misses, NUMA traffic, storage latency/queueing, and network queue usage. Run controlled A/B tests with the neighbor idle, active, and resource-limited. If latency degradation follows one shared resource and improves under isolation/reservation, the neighbor is causal. Choose placement or resource controls based on the measured bottleneck rather than assuming CPU percentage captures interference.', 'verification_details': 'Must compare colocated versus isolated behavior, measure shared-resource contention beyond CPU average, and validate with resource isolation/limits.', 'tags': ['noisy-neighbor', 'colocation', 'resource-contention', 'capacity'], 'verification_method': 'rubric'}, {'id': 'trouble-littles-law-queue', 'concept': 'queue-growth-littles-law-capacity', 'domain': 'engineering-reasoning', 'subdomain': 'queueing', 'difficulty': 'advanced', 'question': 'A request queue grows steadily even though the service still completes many requests per second. Arrival rate is slightly above sustainable service rate. Explain the queue behavior and what to measure.', 'answer': "When long-run arrival rate exceeds sustainable completion rate, backlog grows without bound until admission, capacity, or traffic changes. Measure arrival rate, completion rate, queue depth, and time-in-system over the same intervals. Little's Law (`L = λW`) is useful in stable regimes, but a continuously growing queue is not in steady state, so applying it blindly can mislead. Restore stability by reducing admitted load, increasing sustainable service capacity, or shedding/degrading work before latency explodes.", 'verification_details': "Must compare arrival versus sustainable service rate, identify unstable backlog growth, use Little's Law only with its steady-state assumptions, and recommend admission/capacity action.", 'tags': ['queueing', 'little-law', 'capacity', 'backlog'], 'verification_method': 'rubric'}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]
BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        PURPOSE,
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
